<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { getCatalogSuggestions, reviewCatalogSuggestion } from '@/api/adminOperationsApi'
import type { AdminCatalogSuggestion } from '@/models/AdminCatalogSuggestion'
import { useAdminCurrentUserStore } from '@/stores/adminCurrentUserStore'
const currentUserStore = useAdminCurrentUserStore()
const items = ref<AdminCatalogSuggestion[]>([]), selected = ref<AdminCatalogSuggestion | null>(null), status = ref(''), comment = ref(''), error = ref(''), isSaving = ref(false)
const canManage = computed(() => currentUserStore.isSystem || currentUserStore.currentUser?.permissions.includes('Admin.Content.Manage') === true)
onMounted(load)
async function load() { try { items.value = await getCatalogSuggestions(status.value) } catch { error.value = 'Не удалось загрузить предложения.' } }
async function review(action: 'approve' | 'reject') { if (!selected.value) return; isSaving.value = true; try { await reviewCatalogSuggestion(selected.value.id, action, comment.value); selected.value = null; await load() } catch { error.value = 'Не удалось обработать предложение.' } finally { isSaving.value = false } }
</script>
<template><section class="operations-page"><h1>Предложения в каталог</h1><div class="operations-toolbar"><SearchSelect v-model="status" :options="[{ value: '', label: 'Все' }, { value: '1', label: 'На модерации' }, { value: '2', label: 'Одобренные' }, { value: '3', label: 'Отклонённые' }]" @change="load" /></div><div v-if="error" class="form-message form-message--error">{{ error }}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Марка</th><th>Модель</th><th>Тип</th><th>Автор</th><th>Статус</th></tr></thead><tbody><tr v-for="item in items" :key="item.id" @click="selected = item; comment = item.adminComment || ''"><td>{{ item.brandName }}</td><td>{{ item.modelName }}</td><td>{{ item.kindText }}</td><td>{{ item.suggestedByEmail || '—' }}</td><td>{{ item.statusText }}</td></tr></tbody></table></div><div v-if="selected" class="modal-backdrop" @click.self="selected = null"><div class="modal-card"><div class="modal-heading"><strong>{{ selected.brandName }} {{ selected.modelName }}</strong><button type="button" @click="selected = null">×</button></div><label><span>Комментарий</span><textarea v-model="comment" rows="4" :disabled="!canManage"></textarea></label><div class="modal-actions"><button v-if="canManage" class="primary-button" :disabled="isSaving || selected.status !== 1" @click="review('approve')">Одобрить</button><button v-if="canManage" class="danger-button" :disabled="isSaving || selected.status !== 1" @click="review('reject')">Отклонить</button><button class="secondary-button" @click="selected = null">{{ canManage ? 'Отмена' : 'Закрыть' }}</button></div></div></div></section></template>
